```tsx
import "./ChipFilter.css";
import { useId } from "react";

export interface ChipOption<T extends string = string> {
  value: T;
  label: string;
}

export interface ChipFilterProps<T extends string = string> {
  label: string;
  options: readonly ChipOption<T>[];
  selected: readonly T[];
  onToggle: (value: T) => void;
}

export function ChipFilter<T extends string = string>({
  label,
  options,
  selected,
  onToggle,
}: ChipFilterProps<T>) {
  const labelId = useId();

  return (
    <div className="chip-filter" role="group" aria-labelledby={labelId}>
      <span id={labelId} className="chip-filter__label">
        {label}
      </span>
      <div className="chip-filter__chips">
        {options.map((option) => {
          const pressed = selected.includes(option.value);
          return (
            <button
              key={option.value}
              type="button"
              className="chip-filter__chip"
              aria-pressed={pressed}
              onClick={() => onToggle(option.value)}
            >
              {option.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}
