.chip-filter {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  color: var(--ink);
}

.chip-filter__label {
  font-size: clamp(0.75rem, 0.7rem + 0.2vw, 0.875rem);
  color: var(--muted);
}

.chip-filter__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.chip-filter__chip {
  font: inherit;
  font-size: clamp(0.8125rem, 0.78rem + 0.15vw, 0.95rem);
  display: inline-flex;
  align-items: center;
  gap: 0.45em;
  min-height: 2.5rem;
  padding: 0.4rem 0.9rem;
  border-radius: 999px;
  border: 1px solid var(--muted);
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease;
}

/* Hollow marker when off. */
.chip-filter__chip::before {
  content: "";
  flex: none;
  width: 0.55em;
  height: 0.55em;
  border-radius: 999px;
  border: 1px solid currentColor;
  box-sizing: border-box;
  transition: background-color 150ms ease;
}

.chip-filter__chip:hover {
  border-color: var(--ink);
}

/* On: filled marker and a wash, so state is not carried by colour alone. */
.chip-filter__chip[aria-pressed="true"] {
  border-color: var(--myelin);
  background: var(--myelin-wash);
}

.chip-filter__chip[aria-pressed="true"]::before {
  background: var(--myelin);
  border-color: var(--myelin);
}

/* Add to the global focus outline; never replace it. */
.chip-filter__chip:focus-visible {
  border-color: var(--cresyl);
}

:root[data-motion="reduce"] .chip-filter__chip,
:root[data-motion="reduce"] .chip-filter__chip::before {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .chip-filter__chip,
  .chip-filter__chip::before {
    transition: none;
  }
}
